"""Blender flame rig for the camper stove; four independent 0..1 custom properties."""

def add_flames(out, burners):
    import bpy,math
    from pathlib import Path
    from mathutils import Vector
    OUT=Path(out)
    # Independent from the static game mesh: runtime flames are generated by the MTA resource.
    for name in ['STOVE_FLAMES','STOVE_CONTROLS']:
     old=bpy.data.collections.get(name)
     if old:
      for o in list(old.objects):bpy.data.objects.remove(o,do_unlink=True)
      bpy.data.collections.remove(old)
    flames=bpy.data.collections.new('STOVE_FLAMES');bpy.context.scene.collection.children.link(flames)
    controls=bpy.data.collections.new('STOVE_CONTROLS');bpy.context.scene.collection.children.link(controls)
    control=bpy.data.objects.new('Stove_Control',None);controls.objects.link(control)
    for i in range(1,5):
     key=f'burner_{i}';control[key]=1.0
     control.id_properties_ui(key).update(min=0,max=1,soft_min=0,soft_max=1,description='0 = off, 1 = full flame')
    
    def emissive(name,color,power):
     mat=bpy.data.materials.get(name) or bpy.data.materials.new(name);mat.use_nodes=True
     ns=mat.node_tree.nodes;ns.clear();out=ns.new('ShaderNodeOutputMaterial');em=ns.new('ShaderNodeEmission');em.inputs['Color'].default_value=(*color,1);em.inputs['Strength'].default_value=power;mat.node_tree.links.new(em.outputs[0],out.inputs[0]);mat.diffuse_color=(*color,1)
     return mat
    blue=emissive('Gas_Flame_Blue',(0.012,0.055,1),2.3)
    cyan=emissive('Gas_Flame_Core',(0.09,0.48,1),3.0)
    
    def drive(obj,path,expr,index=-1,burner=1,phase=0):
     f=obj.driver_add(path) if index<0 else obj.driver_add(path,index)
     d=f.driver;d.type='SCRIPTED';v=d.variables.new();v.name='level';v.type='SINGLE_PROP';v.targets[0].id=control;v.targets[0].data_path=f'["burner_{burner}"]';d.expression=expr
    
    def jetmesh(name,radius,height,material):
     verts=[];faces=[];segments=8
     for k,(h,r) in enumerate([(0,.55),(.2,1),(.5,.7),(.8,.32),(1,.015)]):
      for j in range(segments):
       a=j*math.tau/segments;verts.append((math.cos(a)*radius*r+height*.08*h*h,math.sin(a)*radius*r,height*h))
      if k:
       for j in range(segments):faces.append(((k-1)*segments+j,(k-1)*segments+(j+1)%segments,k*segments+(j+1)%segments,k*segments+j))
     faces.append(tuple(reversed(range(segments))));faces.append(tuple(4*segments+j for j in range(segments)))
     mesh=bpy.data.meshes.new(name);mesh.from_pydata(verts,[],faces);mesh.materials.append(material)
     for p in mesh.polygons:p.use_smooth=True
     return mesh
    outermesh=jetmesh('Blue_Jet_Geometry',.006,.043,blue);innermesh=jetmesh('Cyan_Core_Geometry',.003,.026,cyan)
    for i,(x,y,r) in enumerate(burners,1):
     for j in range(12):
      a=j*math.tau/12;phase=j*1.7+i
      for suffix,mesh in [('Outer',outermesh),('Core',innermesh)]:
       o=bpy.data.objects.new(f'Flame_Burner_{i}_Jet_{j+1:02d}_{suffix}',mesh);flames.objects.link(o);o.parent=control;o.location=(x+math.cos(a)*r*.72,y+math.sin(a)*r*.72,.581);o.rotation_euler.z=a
       drive(o,'scale','sqrt(max(0,min(1,level)))',0,i);drive(o,'scale','sqrt(max(0,min(1,level)))',1,i)
       drive(o,'scale',f'max(0,min(1,level))*(1+0.10*sin(frame*0.58+{phase}))',2,i)
       drive(o,'hide_render','level<=0',burner=i);drive(o,'hide_viewport','level<=0',burner=i)
     bpy.ops.object.light_add(type='POINT',location=(x,y,.61));light=bpy.context.object;light.name=f'Burner_{i}_Glow'
     for c in list(light.users_collection):c.objects.unlink(light)
     flames.objects.link(light);light.parent=control;light.data.color=(.035,.20,1);light.data.shadow_soft_size=.07
     f=light.data.driver_add('energy');v=f.driver.variables.new();v.name='level';v.targets[0].id=control;v.targets[0].data_path=f'["burner_{i}"]';f.driver.expression='max(0,min(1,level))*1.6'
    api='''import bpy\n\ndef set_burner(index, intensity):\n    if index not in (1, 2, 3, 4):\n        raise ValueError("Burner must be 1..4")\n    intensity = float(intensity)\n    if not 0 <= intensity <= 1:\n        raise ValueError("Intensity must be 0..1")\n    control = bpy.data.objects["Stove_Control"]\n    control[f"burner_{index}"] = intensity\n    control.update_tag()\n    bpy.context.view_layer.update()\n\n# set_burner(1, 0.5)  # front left at half power\n# set_burner(2, 0)    # front right off\n'''
    text=bpy.data.texts.get('stove_controls.py') or bpy.data.texts.new('stove_controls.py');text.clear();text.write(api);(OUT/'stove_controls.py').write_text(api)
